import unittest
from cart import total_cents, customer_label, clean_name

class CartTests(unittest.TestCase):
    def test_nonempty(self):
        self.assertEqual(total_cents([(125, 2), (50, 1)]), 300)

    def test_label(self):
        self.assertEqual(customer_label('Ada'), 'Customer: Ada')

    def test_label_normalizes_name(self):
        cases = [
            ('  Ada  ', 'Customer: Ada'),
            ('  Ada   van  LOVELACE  ', 'Customer: Ada van LOVELACE'),
            ('', 'Customer: '),
            ('   ', 'Customer: '),
            ('\tAda\n Lovelace\t', 'Customer: Ada Lovelace'),
        ]
        for name, expected in cases:
            with self.subTest(name=name):
                self.assertEqual(customer_label(name), expected)

    def test_clean_name(self):
        cases = [
            ('Ada', 'Ada'),
            ('  Ada  ', 'Ada'),
            ('  Ada   van  LOVELACE  ', 'Ada van LOVELACE'),
            ('', ''),
            ('   ', ''),
            ('\tAda\n Lovelace\t', 'Ada Lovelace'),
        ]
        for name, expected in cases:
            with self.subTest(name=name):
                self.assertEqual(clean_name(name), expected)
